-- Deterministic Phase 2.7.2 synchronization bootstrap. Safe to run repeatedly.
begin;
create extension if not exists pgcrypto;
create table if not exists public.sync_schema_version(required_version text primary key, applied_at timestamptz not null default now());
insert into public.sync_schema_version(required_version) values('2.7.2') on conflict(required_version) do update set applied_at=now();
create table if not exists public.sync_operations(operation_id uuid primary key,tenant_id uuid not null,idempotency_key text not null,entity_type text not null,entity_id uuid not null,operation text not null,local_version bigint not null,payload jsonb not null,accepted_at timestamptz not null default now(),unique(tenant_id,idempotency_key));
create table if not exists public.sync_changes(sequence_id bigint generated always as identity primary key,tenant_id uuid not null,entity_type text not null,entity_id uuid not null,server_version bigint not null,payload jsonb not null,deleted boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.facility_profiles(id uuid primary key,tenant_id uuid not null,arabic_name text not null default '',english_name text not null default '',logo_path text,policy integer not null default 1,updated_at bigint not null default 0,is_deleted boolean not null default false);
create table if not exists public.print_logs(id uuid primary key,tenant_id uuid not null,visit_id uuid not null,printed_at bigint not null,is_deleted boolean not null default false);
create unique index if not exists idx_sync_ops_tenant_idem on public.sync_operations(tenant_id,idempotency_key);
create index if not exists idx_sync_changes_tenant_cursor on public.sync_changes(tenant_id,sequence_id);
create index if not exists idx_facility_profiles_tenant on public.facility_profiles(tenant_id);
create index if not exists idx_print_logs_tenant on public.print_logs(tenant_id);
alter table public.sync_operations enable row level security; alter table public.sync_changes enable row level security; alter table public.facility_profiles enable row level security; alter table public.print_logs enable row level security;
drop policy if exists sync_ops_tenant on public.sync_operations; create policy sync_ops_tenant on public.sync_operations for select to authenticated using(tenant_id=public.current_tenant_id());
drop policy if exists sync_changes_tenant on public.sync_changes; create policy sync_changes_tenant on public.sync_changes for select to authenticated using(tenant_id=public.current_tenant_id());
drop policy if exists facility_profiles_tenant on public.facility_profiles; create policy facility_profiles_tenant on public.facility_profiles for all to authenticated using(tenant_id=public.current_tenant_id()) with check(tenant_id=public.current_tenant_id());
drop policy if exists print_logs_tenant on public.print_logs; create policy print_logs_tenant on public.print_logs for all to authenticated using(tenant_id=public.current_tenant_id()) with check(tenant_id=public.current_tenant_id());
drop function if exists public.sync_push(jsonb); drop function if exists public.sync_pull(bigint,integer); drop function if exists public.sync_push_test(text);
create or replace function public.sync_push(p jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare t uuid:=public.current_tenant_id(); et text:=upper(p->>'entity_type'); op uuid:=(p->>'operation_id')::uuid; eid uuid:=(p->>'entity_id')::uuid; idem text:=p->>'idempotency_key'; sv bigint:=extract(epoch from clock_timestamp())::bigint; begin if t is null then raise exception 'tenant not resolved' using errcode='42501'; end if; if et not in('COMPANY','REPRESENTATIVE','VISIT','FACILITY_PROFILE','PRINT_LOG') then raise exception 'unsupported entity type'; end if; if exists(select 1 from sync_operations where tenant_id=t and idempotency_key=idem) then return jsonb_build_object('accepted',true,'duplicate',true,'server_version',sv); end if; insert into sync_operations(operation_id,tenant_id,idempotency_key,entity_type,entity_id,operation,local_version,payload) values(op,t,idem,et,eid,coalesce(p->>'operation','UPDATE'),coalesce((p->>'local_version')::bigint,0),coalesce(p->'payload','{}')); insert into sync_changes(tenant_id,entity_type,entity_id,server_version,payload,deleted) values(t,et,eid,sv,coalesce(p->'payload','{}'),coalesce((p->>'operation')='DELETE',false)); return jsonb_build_object('accepted',true,'duplicate',false,'server_version',sv); end; $$;
create or replace function public.sync_pull(p_cursor bigint default 0,p_limit integer default 100) returns table(sequence_id bigint,entity_type text,entity_id uuid,server_version bigint,payload jsonb,deleted boolean) language sql security invoker set search_path=public as $$ select c.sequence_id,c.entity_type,c.entity_id,c.server_version,c.payload,c.deleted from sync_changes c where c.tenant_id=public.current_tenant_id() and c.sequence_id>coalesce(p_cursor,0) order by c.sequence_id limit least(greatest(coalesce(p_limit,100),1),500) $$;
create or replace function public.sync_push_test(entity text) returns jsonb language plpgsql security definer set search_path=public as $$ begin if upper(entity) not in('COMPANY','REPRESENTATIVE','VISIT','FACILITY_PROFILE','PRINT_LOG') then raise exception 'unsupported entity type'; end if; return jsonb_build_object('supported',true,'entity_type',upper(entity),'required_version','2.7.2'); end $$;
grant execute on function public.sync_push(jsonb) to authenticated; grant execute on function public.sync_pull(bigint,integer) to authenticated; grant execute on function public.sync_push_test(text) to service_role;
commit;
